toad_implementation.code_blueprint:
canvas {
  size: 800px 800px;
  fill: #FFF9F2;
  font-family: "Nunito, sans-serif";
}

>skyBlue = #7EB0D5;
>meadow = #B2E061;
>buttercup = #FDCB6E;
>softBrown = #594236;

circle #sunHead {
  at: center of canvas offset 0px -60px;
  size: 260px;
  fill: >buttercup;
}

circle #cloudLeft {
  at: center of #sunHead offset -120px 80px;
  size: 160px;
  fill: #FFFFFF;
}

circle #cloudRight {
  at: center of #sunHead offset 120px 80px;
  size: 180px;
  fill: #FFFFFF;
}

text #bookTitle {
  at: below #sunHead offset 100px;
  content: "KLEINER BÄR ENTDECKT DIE WELT";
  font-size: 26px;
  font-weight: 800;
  color: >softBrown;
}

text #storyTeaser {
  at: below #bookTitle offset 14px;
  size: 520px;
  content: "Eine liebevolle Geschichte über Neugier, Freundschaft und den Mut, die ersten eigenen Schritte zu wagen.";
  font-size: 15px;
  color: #7A695E;
}
